import React from "react";
import { NewsAnalysis } from "@/lib/types";
import { TrendingUp, TrendingDown, Minus, ShieldAlert, Zap, BookOpen } from "lucide-react";

interface AnalysisSummaryProps {
  analysis: NewsAnalysis;
}

const AnalysisSummary: React.FC<AnalysisSummaryProps> = ({ analysis }) => {
  const getSentimentIcon = () => {
    switch (analysis.overall_sentiment) {
      case "bullish": return <TrendingUp className="w-5 h-5 text-emerald-400" />;
      case "bearish": return <TrendingDown className="w-5 h-5 text-rose-400" />;
      default: return <Minus className="w-5 h-5 text-slate-400" />;
    }
  };

  const getSentimentColor = () => {
    switch (analysis.overall_sentiment) {
      case "bullish": return "text-emerald-400 bg-emerald-400/10 border-emerald-400/20";
      case "bearish": return "text-rose-400 bg-rose-400/10 border-rose-400/20";
      default: return "text-slate-400 bg-slate-400/10 border-slate-400/20";
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between p-6 bg-slate-900 border border-slate-800 rounded-3xl shadow-xl shadow-blue-900/5">
        <div className="flex items-center space-x-4">
          <div className={`p-3 rounded-2xl border ${getSentimentColor()}`}>
            {getSentimentIcon()}
          </div>
          <div>
            <p className="text-sm text-slate-500 font-medium uppercase tracking-wider">Overall Sentiment</p>
            <h2 className="text-2xl font-black capitalize tracking-tight">{analysis.overall_sentiment}</h2>
          </div>
        </div>
        <div className="text-right">
          <p className="text-sm text-slate-500 font-medium uppercase tracking-wider">Score</p>
          <p className="text-3xl font-black text-blue-400">{(analysis.sentiment_score * 100).toFixed(0)}%</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="p-6 bg-slate-900 border border-slate-800 rounded-3xl">
          <div className="flex items-center space-x-2 mb-4">
            <Zap className="w-5 h-5 text-amber-400" />
            <h3 className="text-lg font-bold">Key Catalysts</h3>
          </div>
          <ul className="space-y-3">
            {analysis.catalysts.map((c, i) => (
              <li key={i} className="flex items-start space-x-2 text-sm text-slate-300">
                <span className="mt-1.5 w-1.5 h-1.5 rounded-full bg-emerald-400 shrink-0" />
                <span>{c}</span>
              </li>
            ))}
          </ul>
        </div>

        <div className="p-6 bg-slate-900 border border-slate-800 rounded-3xl">
          <div className="flex items-center space-x-2 mb-4">
            <ShieldAlert className="w-5 h-5 text-rose-400" />
            <h3 className="text-lg font-bold">Risk Factors</h3>
          </div>
          <ul className="space-y-3">
            {analysis.risks.map((r, i) => (
              <li key={i} className="flex items-start space-x-2 text-sm text-slate-300">
                <span className="mt-1.5 w-1.5 h-1.5 rounded-full bg-rose-400 shrink-0" />
                <span>{r}</span>
              </li>
            ))}
          </ul>
        </div>
      </div>

      <div className="p-8 bg-gradient-to-br from-slate-900 to-indigo-950/20 border border-slate-800 rounded-3xl relative overflow-hidden group">
        <div className="absolute top-0 right-0 p-8 opacity-5">
          <BookOpen className="w-32 h-32 text-blue-400" />
        </div>
        <h3 className="text-xl font-black mb-4 flex items-center space-x-2">
          <span>Analyst Summary</span>
        </h3>
        <p className="text-slate-300 leading-relaxed relative z-10 text-lg">
          {analysis.summary}
        </p>
      </div>
    </div>
  );
};

export default AnalysisSummary;
